style.css:
@-moz-document domain("ogame.gameforge.com") {
/* 1. Déplacer l'EventBox (mouvements de flottes) sur le côté gauche */
    #eventboxContent {
        position: fixed !important;
        top: 150px !important;    /* Ajustez selon la hauteur de votre header */
        left: 10px !important;     /* Aligne le bloc sur le bord gauche de l'écran */
        width: 210px !important;   /* Largeur équivalente à la colonne vide de gauche */
        max-height: 75vh !important;
        overflow-y: auto !important; /* Ajoute une barre de défilement si vous avez trop de flottes */
        background: rgba(10, 14, 23, 0.95) !important; /* Fond sombre pour la lisibilité */
        border: 1px solid #333 !important;
        z-index: 1999 !important;  /* Force l'affichage au premier plan */
        padding: 5px !important;
        border-radius: 5px;
    }

    /* 2. Forcer l'affichage permanent et déplié des lignes de flottes */
    #eventboxContent table, 
    #eventContent, 
    .eventList {
        display: block !important;
        width: 100% !important;
    }

    /* 3. Réduire la taille du texte pour que les lignes tiennent sur la gauche */
    #eventboxContent td, 
    #eventboxContent span,
    .eventList .text {
        font-size: 11px !important;
        padding: 2px 0 !important;
    }

    /* 4. Masquer ou décaler le menu de gauche d'origine pour éviter les superpositions */
    #menuTable {
        opacity: 0.15 !important; /* Rend le menu d'origine presque invisible */
        transition: opacity 0.2s;
    }
    #menuTable:hover {
        opacity: 1 !important;    /* Redevient visible si vous passez la souris dessus pour cliquer */
    }
}
